#!/usr/bin/env python3
import base64, io, tarfile, pathlib

ARCHIVE_B64 = """[... ELLIPSIZATION ...]"""

root = pathlib.Path(__file__).resolve().parent
payload = base64.b64decode(ARCHIVE_B64)
with tarfile.open(fileobj=io.BytesIO(payload), mode="r:gz") as tf:
    for member in tf.getmembers():
        name = member.name
        if name.startswith("./"):
            name = name[2:]
        if not name or name.startswith(".git/") or "/.git/" in name:
            continue
        member.name = name
        tf.extract(member, root)
print("Tianji knowledge base seed expanded.")
